"use client";

/**
 * Launch title: a three-shot announcement. A small eyebrow line, a cut to the
 * product name assembling large letter by letter, then a cut to the tagline
 * while a primary band sweeps across one word.
 *
 * Written by Better Design.
 */
import { loadFont } from "@remotion/google-fonts/InterTight";
import { AbsoluteFill, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER_TIGHT } = loadFont("normal", { weights: ["500", "600", "800"], subsets: ["latin"] });

/** Where each shot starts. */
const NAME_AT = 34;
const TAGLINE_AT = 84;
/** Frames between one letter of the name and the next. */
const LETTER_STAGGER = 2.2;
const SWEEP_AT = 16;
const SWEEP_FRAMES = 20;

export interface LaunchTitleProps {
  /** The small line that opens the film. */
  eyebrow?: string;
  /** The product name, assembled large in the second shot. */
  name?: string;
  /** One line under the name in the last shot. */
  tagline?: string;
  /** A word in the tagline that the primary band sweeps across. Matched without case. */
  accent?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter Tight. */
  font?: string;
}

const bare = (word: string): string => word.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");

/** Eyebrow, then the name assembling, then the tagline with one swept word. */
export function LaunchTitle({
  eyebrow = "Introducing",
  name = "Your product",
  tagline = "The fastest way to ship your next idea.",
  accent = "fastest",
  theme: themeOverride,
  font,
}: LaunchTitleProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER_TIGHT);

  const shot = frame < NAME_AT ? 0 : frame < TAGLINE_AT ? 1 : 2;

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family, color: theme.foreground }}>
      {shot === 0 ? <Eyebrow text={eyebrow} frame={frame} theme={theme} /> : null}
      {shot === 1 ? <Name text={name} frame={frame - NAME_AT} fps={fps} theme={theme} /> : null}
      {shot === 2 ? <Tagline name={name} text={tagline} accent={accent} frame={frame - TAGLINE_AT} theme={theme} /> : null}
    </AbsoluteFill>
  );
}

function Eyebrow({ text, frame, theme }: { text: string; frame: number; theme: VideoTheme }) {
  const t = easings.out(progress(frame, 2, 16));
  const line = easings.out(progress(frame, 6, 20));
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 28, opacity: t, transform: `translateY(${(1 - t) * 14}px)` }}>
      <div style={{ width: 120 * line, height: 2, background: withAlpha(theme.foreground, 0.25) }} />
      <div style={{ display: "flex", alignItems: "center", gap: 16, fontSize: 48, fontWeight: 500, color: theme.mutedForeground }}>
        <div style={{ width: 14, height: 14, borderRadius: 7, background: theme.primary, transform: `scale(${t})` }} />
        {text}
      </div>
      <div style={{ width: 120 * line, height: 2, background: withAlpha(theme.foreground, 0.25) }} />
    </div>
  );
}

function Name({ text, frame, fps, theme }: { text: string; frame: number; fps: number; theme: VideoTheme }) {
  const letters = Array.from(text);
  return (
    <div style={{ display: "flex", fontSize: 220, fontWeight: 800, letterSpacing: "-0.05em", lineHeight: 1, whiteSpace: "pre" }}>
      {letters.map((letter, i) => {
        const s = spring({ frame: frame - i * LETTER_STAGGER, fps, config: springs.snappy });
        const blur = (1 - s) * 18;
        return (
          <span
            key={`${letter}-${i}`}
            style={{
              display: "inline-block",
              opacity: Math.min(1, s * 1.4),
              filter: `blur(${blur}px)`,
              transform: `translateY(${(1 - s) * 90}px) scale(${0.7 + 0.3 * s})`,
            }}
          >
            {letter}
          </span>
        );
      })}
    </div>
  );
}

function Tagline({ name, text, accent, frame, theme }: { name: string; text: string; accent: string; frame: number; theme: VideoTheme }) {
  const enter = easings.out(progress(frame, 0, 16));
  const sweep = easings.inOut(progress(frame, SWEEP_AT, SWEEP_FRAMES));
  const words = text.split(/\s+/).filter(Boolean);
  const target = bare(accent);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 40, opacity: enter, transform: `translateY(${(1 - enter) * 20}px)` }}>
      <div style={{ fontSize: 56, fontWeight: 600, letterSpacing: "-0.03em", color: theme.mutedForeground }}>{name}</div>
      <div style={{ maxWidth: 1500, textAlign: "center", fontSize: 104, fontWeight: 800, letterSpacing: "-0.04em", lineHeight: 1.12, textWrap: "balance" }}>
        {words.map((word, i) => {
          const hit = target !== "" && bare(word) === target;
          return (
            <span key={`${word}-${i}`} style={{ position: "relative", display: "inline-block", marginRight: i < words.length - 1 ? "0.24em" : 0 }}>
              {hit ? (
                <span
                  style={{
                    position: "absolute",
                    left: "-0.12em",
                    right: "-0.12em",
                    top: "0.06em",
                    bottom: "0.02em",
                    borderRadius: theme.radius,
                    background: theme.primary,
                    transformOrigin: "left center",
                    transform: `scaleX(${sweep})`,
                  }}
                />
              ) : null}
              <span style={{ position: "relative", color: theme.foreground }}>{word}</span>
              {hit ? (
                <span style={{ position: "absolute", left: 0, top: 0, color: theme.primaryForeground, clipPath: `inset(-0.3em ${(1 - sweep) * 100}% -0.3em -0.1em)` }}>{word}</span>
              ) : null}
            </span>
          );
        })}
      </div>
    </div>
  );
}
